// Image preview, generated by Rust (works for HEIC, TGA, TIFF… that the webview can't show)
// and only once the card scrolls into view.
import { useEffect, useRef, useState } from "react";
import { api } from "../../lib/api";
import type { FileInfo } from "../../lib/types";

const cache = new Map<string, string>(); // path → blob URL, kept for the session

export function Thumbnail({ file }: { file: FileInfo }) {
  const ref = useRef<HTMLDivElement>(null);
  const [url, setUrl] = useState(() => cache.get(file.path));
  const canPreview = file.kind === "image" && file.operations.length > 0;

  useEffect(() => {
    if (url || !canPreview || !ref.current) return;
    const el = ref.current;
    const io = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) return;
        io.disconnect();
        api
          .thumbnail(file.path)
          .then((buf) => {
            const u = URL.createObjectURL(new Blob([buf]));
            cache.set(file.path, u);
            setUrl(u);
          })
          .catch(() => {});
      },
      { rootMargin: "200px" },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [file.path, url, canPreview]);

  return (
    <div
      ref={ref}
      className="relative h-14 w-14 shrink-0 overflow-hidden rounded-lg bg-surface-2"
      style={url ? { backgroundImage: "repeating-conic-gradient(#8883 0 25%, transparent 0 50%)", backgroundSize: "12px 12px" } : undefined}
    >
      {url && <img src={url} alt="" className="h-full w-full object-cover" draggable={false} />}
      <span className="absolute bottom-0.5 left-0.5 rounded bg-black/70 px-1 text-[10px] font-bold tracking-wide text-white">
        {file.formatLabel ?? "?"}
      </span>
    </div>
  );
}
